# The rates set on a sheet, by grade.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
  govern: [ readonly-transaction ]
# Set a grade's rate. Validate first so a bad grade or percent is a 400, not a 404.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.rate.AuditRateSet
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
  govern: [ transaction ]
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved rate. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditRateSet {
    public void audit(@Val Sheet sheet, @Val Rate rate, HttpServletRequest request, Audit audit) {
        audit.record("RATE_SET sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() == null ? "" : " from=" + rate.from()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidRate {
    public void handle(@Parameter InvalidRateException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.rate;

/**
 * A rate with a grade other than A, B or C, a percent that is not 0.00 or more with two decimals,
 * or a from-date that is not a date.
 */
public class InvalidRateException extends Exception {
    public InvalidRateException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated rate request: its grade, its percent scaled to two decimals, and its from-date (or null). */
public record RateInput(String grade, BigDecimal pct, LocalDate from) {
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The rates store: at most one rate per grade and from-date, kept per sheet. */
@Repository
public class RateRepository {

    private static final RowMapper<Rate> ROW = (rs, n) -> new Rate(rs.getString("sheet_id"),
            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class));

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates, by grade then from-date (none first). */
    public List<Rate> findAll(String sheetId) {
        return jdbc.query("SELECT sheet_id, grade, pct, from_date FROM rate WHERE sheet_id = ?"
                + " ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    }

    /** Set the grade's rate from its from-date, replacing any it had for that from-date. */
    public void save(Rate rate) {
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                rate.sheetId(), rate.grade(), rate.from());
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date) VALUES (?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.pct(), rate.from());
    }
}
package net.officefloor.hq.app.rate;

/**
 * A rate as the screen sends it: a grade (A, B or C), a percent with up to two decimals, and an
 * optional from-date (yyyy-MM-dd; blank for from the beginning of time).
 */
public record RateRequest(String grade, String pct, String from) {
}
package net.officefloor.hq.app.rate;

/** A rate, as the screen reads it: its grade, its percent with two decimals, and its from-date ('' for none). */
public record RateResponse(String grade, String pct, String from) {
    public static RateResponse from(Rate rate) {
        return new RateResponse(rate.grade(), rate.pct().toPlainString(),
                rate.from() == null ? "" : rate.from().toString());
    }
}
package net.officefloor.hq.app.rate;

import java.util.List;

/** The rates set on a sheet, by grade then from-date (none first). */
public record RatesResponse(List<RateResponse> rates) {
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRate {
    public void respond(@Val Rate rate, ObjectResponse<RateResponse> response) {
        response.send(RateResponse.from(rate));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRates {
    public void respond(@Val Sheet sheet, RateRepository repository,
            ObjectResponse<RatesResponse> response) {
        response.send(new RatesResponse(
                repository.findAll(sheet.id()).stream().map(RateResponse::from).toList()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class SaveRate {
    public void save(@Val RateInput input, @Val Sheet sheet, RateRepository repository,
            Out<Rate> rateOut) {
        Rate rate = new Rate(sheet.id(), input.grade(), input.pct(), input.from());
        repository.save(rate);
        rateOut.set(rate);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern PCT = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");

    public void validate(@RequestBody RateRequest request, Out<RateInput> body)
            throws InvalidRateException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) throw new InvalidRateException("A grade is one of A, B or C");
        String pct = request.pct() == null ? "" : request.pct().trim();
        if (pct.isEmpty()) throw new InvalidRateException("A rate is required");
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidRateException("A rate is a percent of 0.00 or more, with up to two decimals");
        }
        String rawFrom = request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!rawFrom.isEmpty()) {
            try {
                from = LocalDate.parse(rawFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidRateException("A from-date is a date, yyyy-MM-dd");
            }
        }
        body.set(new RateInput(grade, new BigDecimal(pct).setScale(2), from));
    }
}
handle:
  class: net.officefloor.hq.app.rate.HandleInvalidRate
-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    grade CHAR(1) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A person's statements: how many have been taken, and the last one's due-total (n/a when it had
-- none) and date (the sheet's today when it was taken). Null total and date until the first.
ALTER TABLE person ADD COLUMN statement_count INT NOT NULL DEFAULT 0;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: stated, with the figure it had then (null: n/a).
-- Its person's next statement rebinds it, or leaves it unbound (live) when it does not count then.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

